contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint40 periodBefore = c.rewardPeriodFinish(token);
        uint256 claimBefore = c.claimableRewards(address(this), token);
        uint256 etherBefore = address(c).balance;

        try c.rewardPerToken(token) returns (uint256 r) {
            assert(
                r == r &&
                c.totalSupply() == tsBefore &&
                c.balanceOf(address(this)) == balBefore &&
                c.rewardPeriodFinish(token) == periodBefore &&
                c.claimableRewards(address(this), token) == claimBefore &&
                address(c).balance == etherBefore
            );
        } catch {
            assert(
                c.totalSupply() == tsBefore &&
                c.balanceOf(address(this)) == balBefore &&
                c.rewardPeriodFinish(token) == periodBefore &&
                c.claimableRewards(address(this), token) == claimBefore &&
                address(c).balance == etherBefore
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public {
        uint256 tsBefore = c.totalSupply();
        uint40 periodBefore = c.rewardPeriodFinish(token);
        uint40 lastUpdateBefore = c.rewardData(token).lastUpdateTime;
        uint216 rateBefore = c.rewardData(token).rewardRate;
        uint216 storedBefore = c.rewardData(token).rewardPerTokenStored;

        uint256 r = c.rewardPerToken(token);

        uint256 expected;
        if (tsBefore == 0) {
            expected = uint256(storedBefore);
        } else {
            uint256 applicable = uint256(periodBefore) < block.timestamp ? uint256(periodBefore) : block.timestamp;
            uint256 elapsed = applicable - uint256(lastUpdateBefore);
            expected = uint256(storedBefore) + (elapsed * uint256(rateBefore) * 1e18) / tsBefore;
        }

        assert(r == expected && c.totalSupply() == tsBefore && c.rewardPeriodFinish(token) == periodBefore);
    }

    receive() external payable {}
}

