contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address forAddr, uint256 amount) public payable {
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddr);

        bool reverted;
        if (amount == 0) {
            try c.stakeFor(forAddr, amount) { reverted = false; } catch { reverted = true; }
        } else {
            // For positive amount, the call may still revert if the caller lacks staking tokens,
            // but we only assert the state effect when it does NOT revert.
            try c.stakeFor(forAddr, amount) { reverted = false; } catch { reverted = true; }
        }

        if (!reverted) {
            assert(c.totalSupply() == supplyBefore + amount && c.balanceOf(forAddr) == balBefore + amount);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

