contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 amount, uint40 initialPeriodFinish) public {
        require(rewardToken != address(0), "token zero");
        c.addReward(rewardToken);

        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        require(beforeFinish == uint40(block.timestamp), "unexpected initial periodFinish");

        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectedRevert = (amount == 0 || msg.sender != c.rewardDistributor());
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 cBalance = IERC20(rewardToken).balanceOf(address(c));

        if (expectedRevert) {
            assert(reverted || cBalance == 0);
        } else {
            assert(!reverted);
            assert(afterFinish == uint40(block.timestamp + c.DURATION()));
            assert(cBalance >= amount);
        }
    }
}

