contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newMigrator, address oldStaking, uint256 amount) public {
        require(newMigrator != address(0));

        c.setMigrator(newMigrator);

        // Read the pre-state that should be preserved on revert.
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        try c.migrateStake(oldStaking, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // msg.sender (this contract) is never the migrator set by the call above,
        // so migrateStake must revert and leave the visible accounting unchanged.
        assert(reverted);
        assert(c.totalSupply() == totalSupplyBefore);
        assert(c.balanceOf(address(this)) == balanceBefore);
        assert(address(c).balance == cBalanceBefore);
    }
}

