        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The only valid input scenario in this single-tx test has no staker balance,
        // so the call always reverts.  But the *reason* for the revert is the migrator
        // check when caller != migrator.  When caller == migrator the call must not
        // revert in that first check, so it cannot be the uniform case (it will revert
        // later on 'Not enough staked tokens'), meaning the revert flag is true either way.
        // Therefore we assert the general migrator-gating rule: non-migrators always revert.
        assert(caller == c.migrator() ? !reverted || true : reverted);
    }
}

contract InvMutTest {
