        c.setMigrator(candidate);

        bool reverted;
        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the migrator gate is exactly the only reason a call can revert
        // specifically because of the caller.  When msg.sender (this test contract) is not
        // the configured migrator, migrateWithdraw must revert.  When it is the migrator,
        // the call must get past the migrator check (any revert then comes from a
        // different check such as amount == 0 or insufficient staked balance).
        if (msg.sender != c.migrator()) {
            assert(reverted);
        } else {
            // If it did not revert, it must have succeeded entirely; otherwise it reverted
            // for a non-migrator reason.  Both are consistent with passing the migrator gate.
            assert(true);
        }
    }

    receive() external payable {}
}

