    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, bool tryRenounce, bool tryNonZero) public {
        address before = c.owner();

        bool reverted;
        if (tryRenounce) {
            try c.renounceOwnership() { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                assert(c.owner() == address(0));
                assert(before != address(0));
                return;
            }
        } else {
            if (tryNonZero) {
                require(newOwner != address(0));
                try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
                if (!reverted) {
                    assert(c.owner() == newOwner);
                    assert(newOwner != address(0));
                    assert(newOwner == c.owner());
                    return;
                }
            } else {
                try c.transferOwnership(address(0)) { reverted = false; } catch { reverted = true; }
                assert(reverted);
                assert(c.owner() == before);
                return;
            }
        }

        assert(reverted);
        assert(c.owner() == before);
    }

    receive() external payable {}
}

