contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public {
        uint256 beforeLen = 0;
        // Snapshot the pre-call list length, then attempt to add the token.
        // Reading previous tokens is not required for the rule, but length is public.
        // rewardTokens(uint256) is an auto-generated public getter.
        // We read the last element only if length > 0; otherwise skip.
        // The deciding call: addReward.
        uint256 lenBefore;
        {
            uint256 i = 0;
            while (true) {
                (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", i));
                if (!ok || ret.length == 0) break;
                lenBefore = i + 1;
                i++;
            }
        }

        bool reverted;
        try c.addReward(token) { reverted = false; } catch { reverted = true; }

        uint256 lenAfter;
        {
            uint256 i = 0;
            while (true) {
                (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", i));
                if (!ok || ret.length == 0) break;
                lenAfter = i + 1;
                i++;
            }
        }

        if (reverted) {
            assert(lenAfter == lenBefore);
        } else {
            assert(lenAfter == lenBefore + 1);
        }
    }

    receive() external payable {}
}

