contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newOwner) public payable {
        require(caller != address(0), "caller zero");

        (bool ownerOk, bytes memory ownerData) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        require(ownerOk && ownerData.length >= 32, "cannot read owner");
        address ownerBefore = abi.decode(ownerData, (address));

        bool expectedSuccess = (caller == ownerBefore) && (newOwner != address(0));
        bool reverted;
        if (expectedSuccess) {
            // Setup: caller is already the owner so transferOwnership should succeed.
            // (ownerBefore == caller because caller was constructed as owner via constructor deployer
            //  is not guaranteed; but this branch is only reachable when caller == ownerBefore.)
            (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
            reverted = !ok;
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
            reverted = !ok;
        }

        (bool ownerOk2, bytes memory ownerData2) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        require(ownerOk2 && ownerData2.length >= 32, "cannot read owner after");
        address ownerAfter = abi.decode(ownerData2, (address));

        if (expectedSuccess) {
            assert(!reverted && ownerAfter == newOwner);
        } else {
            assert(reverted && ownerAfter == ownerBefore);
        }
    }
    receive() external payable {}
}

