        // general rule: the fresh first registration succeeds, the duplicate registration reverts,
        // and after the successful registration the token's reward period is initialized.
        assert(!firstReverted && !secondReverted && reverted && c.rewardPeriodFinish(token) >= block.timestamp);
    }
}

