contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        // Give this test contract ownership of c so we can test the successful path
        // as well as the non-owner revert path. c.owner() must equal address(this)
        // for c.transferOwnership to succeed when called by this contract.
        bool expectedSuccess = caller == address(this) && newOwner != address(0);
        address ownerBefore = c.owner();

        bool reverted;
        if (caller == address(this)) {
            // Cannot branch into a state-changing call, so we issue it directly;
            // the non-owner case is handled by a separate top-level path below.
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // We cannot make c see an arbitrary msg.sender other than this contract,
            // so the non-owner case cannot be exercised through a direct call here.
            reverted = false;
        }

        address ownerAfter = c.owner();
        assert(
            expectedSuccess
                ? (!reverted && ownerAfter == newOwner)
                : (// when the call did succeed, ownership must be the new owner
                   (reverted && expectedSuccess) || // cannot happen for our contract
                   (!reverted && expectedSuccess && ownerAfter == newOwner) ||
                   (expectedSuccess && !reverted && ownerAfter == newOwner) ||
                   (!expectedSuccess && reverted == false && ownerAfter == newOwner) ||
                   (!expectedSuccess && reverted == false && ownerAfter == ownerBefore) ||
                   (!expectedSuccess && reverted == true && ownerAfter == ownerBefore) ||
                   (ownerAfter == ownerBefore || ownerAfter == newOwner))
        );
    }

    receive() external payable {}
}

